#include <iostream>
using namespace std;

int tree[100001], n;

int lowbit(int x) { return x & (-x); }

void add(int i, int v) {
    for (; i <= n; i += lowbit(i)) tree[i] += v;
}

int sum(int i) {
    int s = 0;
    for (; i > 0; i -= lowbit(i)) s += tree[i];
    return s;
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) {
        int x; cin >> x;
        add(i, x);
    }
    int l, r;
    cin >> l >> r;
    cout << sum(r) - sum(l-1) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int tree[400001], a[100001];

void build(int p, int l, int r) {
    if (l == r) { tree[p] = a[l]; return; }
    int mid = (l + r) / 2;
    build(2*p, l, mid);
    build(2*p+1, mid+1, r);
    tree[p] = tree[2*p] + tree[2*p+1];
}

int query(int p, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return tree[p];
    int mid = (l + r) / 2, sum = 0;
    if (ql <= mid) sum += query(2*p, l, mid, ql, qr);
    if (qr > mid) sum += query(2*p+1, mid+1, r, ql, qr);
    return sum;
}

